import Foundation
import Hokusai

/// Fixtures are generated by this code, so they carry no third-party license: everything under
/// `examples/fixtures` is released under the repository's MIT license.
enum Fixtures {
    static func generate(into directory: URL) async throws {
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        try await write(scene(width: 1600, height: 1000), to: directory.appending(path: "scene.png"))
        try await write(emblem(size: 400), to: directory.appending(path: "emblem.png"))
        try await write(gradientMask(width: 1600, height: 1000), to: directory.appending(path: "mask.png"))
        try await writeOrientedJPEG(into: directory.appending(path: "phone.jpg"))
    }

    private static func write(_ image: Hokusai, to url: URL) async throws {
        _ = try await image.png().write(to: url)
    }

    // MARK: - Scene: a landscape with an off-centre subject

    /// 1600 × 1000. The detailed subject (sun and lighthouse) is on the right third, so cover crops,
    /// `attention` and `entropy` visibly differ from a centred crop.
    static func scene(width: Int, height: Int) throws -> Hokusai {
        var pixels = [UInt8](repeating: 255, count: width * height * 3)
        let horizon = Double(height) * 0.62
        let sunX = Double(width) * 0.74, sunY = Double(height) * 0.30, sunR = Double(height) * 0.085
        let towerX = Double(width) * 0.74
        for y in 0..<height {
            for x in 0..<width {
                let fx = Double(x), fy = Double(y)
                var r: Double, g: Double, b: Double
                if fy < horizon {
                    let t = fy / horizon                       // sky: deep blue to warm light
                    r = 40 + 190 * t * t; g = 70 + 130 * t; b = 150 + 70 * t
                } else {
                    let t = (fy - horizon) / (Double(height) - horizon)   // sea: dark ripples
                    let ripple = sin(fx * 0.045 + fy * 0.2) * 9 + sin(fx * 0.013 - fy * 0.35) * 6
                    r = 20 + 20 * t + ripple * 0.4; g = 70 - 25 * t + ripple; b = 110 - 30 * t + ripple * 1.3
                }
                // Distant hills.
                let hill = horizon - 40 - 35 * sin(fx * 0.004 + 1) - 22 * sin(fx * 0.011)
                if fy > hill && fy < horizon { r = 38; g = 56; b = 70 }
                // Sun with a glow.
                let d = ((fx - sunX) * (fx - sunX) + (fy - sunY) * (fy - sunY)).squareRoot()
                if d < sunR { r = 255; g = 214; b = 90 }
                else if d < sunR * 3 { let k = 1 - (d - sunR) / (sunR * 2); r += 90 * k; g += 60 * k; b += 10 * k }
                // Lighthouse: tapered red and white bands on a rock.
                let towerTop = horizon - 330, towerBase = horizon + 8
                if fy > towerTop && fy < towerBase {
                    let t = (fy - towerTop) / (towerBase - towerTop)
                    let half = 14 + 22 * t
                    if abs(fx - towerX) < half {
                        let band = Int((fy - towerTop) / 42) % 2 == 0
                        r = band ? 205 : 245; g = band ? 40 : 245; b = band ? 40 : 245
                    }
                }
                if fy > towerTop - 34 && fy <= towerTop && abs(fx - towerX) < 26 { r = 40; g = 40; b = 48 }
                if fy > towerTop - 50 && fy <= towerTop - 34 && abs(fx - towerX) < 8 { r = 255; g = 235; b = 130 }
                if fy > horizon - 10 && fy < horizon + 46 && abs(fx - towerX) < 34 + (fy - horizon + 10) * 1.7 { r = 60; g = 55; b = 52 }
                let i = (y * width + x) * 3
                pixels[i] = UInt8(max(0, min(255, r))); pixels[i + 1] = UInt8(max(0, min(255, g)))
                pixels[i + 2] = UInt8(max(0, min(255, b)))
            }
        }
        return try Hokusai(raw: Data(pixels), width: width, height: height, format: .rgb8)
    }

    // MARK: - Emblem: a logo with real transparency

    static func emblem(size: Int) throws -> Hokusai {
        var pixels = [UInt8](repeating: 0, count: size * size * 4)
        let c = Double(size) / 2
        for y in 0..<size {
            for x in 0..<size {
                let dx = Double(x) - c + 0.5, dy = Double(y) - c + 0.5
                let d = (dx * dx + dy * dy).squareRoot()
                var rgba: (UInt8, UInt8, UInt8, UInt8) = (0, 0, 0, 0)
                if d < c - 4 {
                    rgba = d > c - 38 ? (24, 60, 120, 255) : (250, 250, 245, 255)
                    if d <= c - 38, abs(dx) < 22 { rgba = (200, 45, 45, 255) }          // a bar
                    if d <= c - 38, abs(dy) < 22, abs(dx) >= 22 { rgba = (200, 45, 45, 255) }
                } else if d < c { rgba = (24, 60, 120, UInt8(255 * max(0, min(1, c - d)))) } // anti-aliased edge
                let i = (y * size + x) * 4
                pixels[i] = rgba.0; pixels[i + 1] = rgba.1; pixels[i + 2] = rgba.2; pixels[i + 3] = rgba.3
            }
        }
        return try Hokusai(raw: Data(pixels), width: size, height: size, format: .rgba8)
    }

    // MARK: - Mask: a soft horizontal ramp, used as alpha

    static func gradientMask(width: Int, height: Int) throws -> Hokusai {
        var pixels = [UInt8](repeating: 0, count: width * height)
        for y in 0..<height { for x in 0..<width { pixels[y * width + x] = UInt8(255 * Double(x) / Double(width - 1)) } }
        return try Hokusai(raw: Data(pixels), width: width, height: height, format: .gray8)
    }

    // MARK: - A phone photo: pixels stored sideways, EXIF orientation 6 ("rotate 90° clockwise to view")

    static func writeOrientedJPEG(into url: URL) async throws {
        // The stored image is 1000 × 1600 (portrait storage of a landscape scene turned on its side).
        let upright = try scene(width: 1600, height: 1000)
        let jpeg = try await upright.rotate(by: 270).jpeg(quality: 90)
            .metadataPolicy(.removeAll).data().data
        try insertOrientation(6, into: jpeg).write(to: url)
    }

    /// Inserts a small EXIF APP1 segment (camera make, software and the orientation tag) after the JPEG's SOI marker.
    static func insertOrientation(_ value: UInt16, into jpeg: Data) -> Data {
        let make = Array("Hokusai\0".utf8)          // 8 bytes, stored after the IFD
        let software = Array("docs-fixture\0".utf8)  // 13 bytes
        let ifdOffset = 8
        let entries = 3
        let dataStart = ifdOffset + 2 + entries * 12 + 4
        func short(_ v: Int) -> [UInt8] { [UInt8(v >> 8), UInt8(v & 0xFF)] }
        func long(_ v: Int) -> [UInt8] { [UInt8(v >> 24), UInt8((v >> 16) & 0xFF), UInt8((v >> 8) & 0xFF), UInt8(v & 0xFF)] }
        var tiff: [UInt8] = [0x4D, 0x4D, 0x00, 0x2A] + long(ifdOffset) + short(entries)
        tiff += short(0x010F) + short(2) + long(make.count) + long(dataStart)                        // Make
        tiff += short(0x0112) + short(3) + long(1) + short(Int(value)) + [0, 0]                      // Orientation
        tiff += short(0x0131) + short(2) + long(software.count) + long(dataStart + make.count)       // Software
        tiff += long(0) + make + software
        let payload = Array("Exif".utf8) + [0, 0] + tiff
        let length = payload.count + 2
        let segment: [UInt8] = [0xFF, 0xE1, UInt8(length >> 8), UInt8(length & 0xFF)] + payload
        var out = Data(jpeg.prefix(2))
        out.append(contentsOf: segment)
        out.append(jpeg.dropFirst(2))
        return out
    }
}
